import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import Map, { Marker, Popup, NavigationControl, GeolocateControl } from 'react-map-gl';
import { MapPin, Navigation, Heart, Utensils, Shirt, BookOpen, Stethoscope, DollarSign, Droplets } from 'lucide-react';
import { useAuth } from '../contexts/AuthContext';
import 'mapbox-gl/dist/mapbox-gl.css';

// Mapbox access token - replace with your actual token
const MAPBOX_ACCESS_TOKEN = process.env.REACT_APP_MAPBOX_ACCESS_TOKEN || 'pk.eyJ1IjoiZXhhbXBsZSIsImEiOiJjbGV4YW1wbGUifQ.example';

const Home = () => {
  const navigate = useNavigate();
  const { api } = useAuth();
  const [orphanages, setOrphanages] = useState([]);
  const [selectedOrphanage, setSelectedOrphanage] = useState(null);
  const [userLocation, setUserLocation] = useState(null);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const mapRef = useRef();

  // Default viewport (India)
  const [viewState, setViewState] = useState({
    longitude: 78.9629,
    latitude: 20.5937,
    zoom: 5
  });

  // Fetch orphanages on component mount
  useEffect(() => {
    fetchOrphanages();
  }, []);

  // Get user location on mount
  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          const { latitude, longitude } = position.coords;
          setUserLocation({ lat: latitude, lng: longitude });
          setViewState(prev => ({
            ...prev,
            longitude,
            latitude,
            zoom: 10
          }));
        },
        (error) => {
          console.log('Geolocation error:', error);
        }
      );
    }
  }, []);

  const fetchOrphanages = async () => {
    try {
      setLoading(true);
      const response = await api.get('/orphanages?verified=true&limit=100');
      setOrphanages(response.data.orphanages);
    } catch (error) {
      console.error('Failed to fetch orphanages:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = () => {
    if (searchQuery.trim()) {
      navigate(`/orphanages?search=${encodeURIComponent(searchQuery.trim())}`);
    }
  };

  const handleRelocate = () => {
    if (userLocation) {
      setViewState(prev => ({
        ...prev,
        longitude: userLocation.lng,
        latitude: userLocation.lat,
        zoom: 12
      }));
    }
  };

  const handleMarkerClick = (orphanage) => {
    setSelectedOrphanage(orphanage);
  };

  const handleDonateClick = (category) => {
    navigate('/donate', { state: { selectedCategory: category } });
  };

  // Donation categories
  const donationCategories = [
    {
      id: 'food',
      title: 'FOOD',
      icon: Utensils,
      color: 'bg-orange-500',
      subcategories: ['PLATE MEALS', 'BULK ITEMS', 'RAW ITEMS', 'PROCESSED ITEMS']
    },
    {
      id: 'clothes',
      title: 'CLOTHES',
      icon: Shirt,
      color: 'bg-blue-500',
      subcategories: ['MEN', 'WOMEN', 'KIDS']
    },
    {
      id: 'education',
      title: 'EDUCATION',
      icon: BookOpen,
      color: 'bg-green-500',
      subcategories: ['STATIONARY', 'BAGS', 'ESSENTIALS']
    },
    {
      id: 'medical',
      title: 'MEDICAL',
      icon: Stethoscope,
      color: 'bg-red-500',
      subcategories: ['COTTON', 'TAPES', 'SCISSOR', 'DETTOL']
    },
    {
      id: 'money',
      title: 'MONEY',
      icon: DollarSign,
      color: 'bg-yellow-500',
      subcategories: ['UPI']
    },
    {
      id: 'hygiene',
      title: 'HYGIENE',
      icon: Droplets,
      color: 'bg-purple-500',
      subcategories: ['BRUSHING ESSENTIALS', 'SOAP', 'SKIN CARE', 'BATHROOM AMENITIES']
    }
  ];

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Page Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-secondary-900">Welcome to NurtureNest</h1>
          <p className="text-secondary-600 mt-2">Connect with orphanages and make a difference through donations</p>
        </div>
        <button
          onClick={handleRelocate}
          className="btn-primary flex items-center space-x-2"
        >
          <Navigation className="w-4 h-4" />
          <span>Relocate</span>
        </button>
      </div>

      {/* Interactive Map Section */}
      <div className="card p-0 overflow-hidden">
        <div className="relative h-96">
          <Map
            ref={mapRef}
            {...viewState}
            onMove={evt => setViewState(evt.viewState)}
            mapStyle="mapbox://styles/mapbox/streets-v11"
            mapboxAccessToken={MAPBOX_ACCESS_TOKEN}
            style={{ width: '100%', height: '100%' }}
          >
            {/* Navigation Controls */}
            <NavigationControl position="top-right" />

            {/* Geolocate Control */}
            <GeolocateControl
              position="top-left"
              trackUserLocation={true}
              showUserLocation={true}
            />

            {/* Orphanage Markers */}
            {orphanages.map((orphanage) => (
              <Marker
                key={orphanage._id}
                longitude={orphanage.address.coordinates.lng}
                latitude={orphanage.address.coordinates.lat}
                anchor="bottom"
                onClick={() => handleMarkerClick(orphanage)}
              >
                <div className="cursor-pointer">
                  <div className="w-6 h-6 bg-green-500 rounded-full border-2 border-white shadow-lg flex items-center justify-center">
                    <MapPin className="w-4 h-4 text-white" />
                  </div>
                </div>
              </Marker>
            ))}

            {/* Selected Orphanage Popup */}
            {selectedOrphanage && (
              <Popup
                longitude={selectedOrphanage.address.coordinates.lng}
                latitude={selectedOrphanage.address.coordinates.lat}
                anchor="bottom"
                onClose={() => setSelectedOrphanage(null)}
                closeButton={true}
                closeOnClick={false}
                maxWidth="300px"
              >
                <div className="p-4">
                  <div className="flex items-center space-x-3 mb-3">
                    <div className="w-12 h-12 bg-primary-100 rounded-lg flex items-center justify-center">
                      <Heart className="w-6 h-6 text-primary-600" />
                    </div>
                    <div>
                      <h3 className="font-semibold text-secondary-900">{selectedOrphanage.name}</h3>
                      <p className="text-sm text-secondary-600">{selectedOrphanage.address.city}, {selectedOrphanage.address.state}</p>
                    </div>
                  </div>

                  <p className="text-sm text-secondary-700 mb-3">{selectedOrphanage.description}</p>

                  <div className="space-y-2">
                    <div className="flex items-center justify-between text-sm">
                      <span className="text-secondary-600">Capacity:</span>
                      <span className="font-medium">{selectedOrphanage.capacity} children</span>
                    </div>
                    <div className="flex items-center justify-between text-sm">
                      <span className="text-secondary-600">Current:</span>
                      <span className="font-medium">{selectedOrphanage.currentOccupancy} children</span>
                    </div>
                  </div>

                  <button
                    onClick={() => {
                      setSelectedOrphanage(null);
                      navigate('/donate', { state: { selectedOrphanage } });
                    }}
                    className="w-full mt-3 btn-primary text-sm py-2"
                  >
                    Donate to this orphanage
                  </button>
                </div>
              </Popup>
            )}
          </Map>
        </div>
      </div>

      {/* Donation Categories Section */}
      <div>
        <h2 className="text-2xl font-bold text-secondary-900 mb-6">What do you want to donate?</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {donationCategories.map((category) => {
            const Icon = category.icon;
            return (
              <div
                key={category.id}
                className="card hover:shadow-lg transition-all duration-200 cursor-pointer group"
                onClick={() => handleDonateClick(category.id)}
              >
                <div className="flex items-center space-x-4 mb-4">
                  <div className={`w-12 h-12 ${category.color} rounded-lg flex items-center justify-center group-hover:scale-110 transition-transform duration-200`}>
                    <Icon className="w-6 h-6 text-white" />
                  </div>
                  <h3 className="text-xl font-bold text-secondary-900">{category.title}</h3>
                </div>

                <div className="space-y-2">
                  {category.subcategories.map((subcategory, index) => (
                    <div
                      key={index}
                      className="text-sm text-secondary-600 hover:text-primary-600 transition-colors duration-200 cursor-pointer"
                      onClick={(e) => {
                        e.stopPropagation();
                        navigate('/donate', { state: { selectedCategory: category.id, selectedSubcategory: subcategory } });
                      }}
                    >
                      {subcategory}
                    </div>
                  ))}
                </div>

                {category.id === 'money' && (
                  <div className="mt-4 p-3 bg-yellow-50 rounded-lg">
                    <div className="text-center">
                      <div className="w-16 h-16 bg-yellow-100 rounded-lg mx-auto mb-2 flex items-center justify-center">
                        <DollarSign className="w-8 h-8 text-yellow-600" />
                      </div>
                      <p className="text-xs text-yellow-700">
                        DISPLAYS THE QR CODE OF THE ORGANIZATION TO DONATE VALUABLE FINANCIAL AID.
                      </p>
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>

      {/* Footer */}
      <div className="text-center py-6 border-t border-secondary-200">
        <p className="text-sm text-secondary-500">© 2023 NURTURENEST</p>
      </div>
    </div>
  );
};

export default Home;
